-- A fixture environment holds only what the real client provides.
-- tests/fixtures/client_api_<client>.lua (generated by tools/generate_client_api.py from
-- Blizzard's UI source and in-game API dumps) classifies every client global and C_* function
-- the addon references. install(env,client) makes each name that client does not provide nil
-- and keeps it nil: a later fixture assignment of that name is dropped, so a stub cannot
-- model an API the game took away. A namespace keeps only the functions the client has.
-- options.fallbacks=true models loadDeprecationFallbacks=1 (the client default): names
-- Blizzard_Deprecated* provides behind that CVar stay assignable. Without it the fixture
-- is a client with the CVar off, which the addon must also survive.
local M={}
M.byProject={[1]='retail',[18]='forever',[19]='mists',[5]='tbc',[2]='era'}
local cache={}
-- env -> {client=,fallbacks=,dropped=} for every environment install() built.
M.installed=setmetatable({},{__mode='k'})
function M.manifest(client)
    if not cache[client] then cache[client]=dofile('tests/fixtures/client_api_'..client..'.lua') end
    return cache[client]
end
-- Every name the client does not provide: name -> 'deprecated'|'removed'|'never'.
function M.absent(client,fallbacks)
    local m=M.manifest(client);local result={}
    if not fallbacks then for name in pairs(m.deprecated) do result[name]='deprecated' end end
    for _,name in ipairs(m.removed) do result[name]='removed' end
    for _,name in ipairs(m.never) do result[name]='never' end
    return result
end
-- The status of one name on a client: 'native', 'deprecated', 'removed', 'never' or nil
-- (unclassified: the addon does not reference it).
function M.status(client,name)
    local m=M.manifest(client)
    if m.deprecated[name]~=nil then return 'deprecated' end
    for _,kind in ipairs({'native','removed','never'}) do
        for _,entry in ipairs(m[kind]) do if entry==name then return kind end end
    end
end
-- Namespace tables stay plain tables (the client's have no metatable, and the compiled
-- condition runtime declines to certify a namespace that has one): the functions the client
-- lacks are removed when the namespace is installed or assigned. A later direct field
-- assignment (e.C_X.F=...) is not intercepted.
local function stripNamespace(namespace,banned,dropped,prefix)
    for field in pairs(banned) do
        if rawget(namespace,field)~=nil then dropped[prefix..'.'..field]=true;rawset(namespace,field,nil) end
    end
end
-- Returns the record of dropped assignments (name -> true) for diagnostics.
function M.install(env,client,options)
    local absent=M.absent(client,options and options.fallbacks)
    local top,fields={},{}
    for name in pairs(absent) do
        local ns,field=name:match('^([%w_]+)%.([%w_]+)$')
        if ns and ns~='Enum' then fields[ns]=fields[ns] or {};fields[ns][field]=true
        elseif not ns then top[name]=true end
    end
    local dropped={}
    for name in pairs(top) do rawset(env,name,nil) end
    for ns,banned in pairs(fields) do
        local namespace=rawget(env,ns)
        if type(namespace)=='table' then stripNamespace(namespace,banned,dropped,ns) end
    end
    -- Reads fall through to the environment's own __index (the host Lua globals, which hold no
    -- WoW name); only assignments are filtered.
    local mt=getmetatable(env)
    if mt==nil then mt={};setmetatable(env,mt) end
    mt.__newindex=function(t,k,v)
        if top[k] then dropped[k]=true;return end
        if fields[k] and type(v)=='table' then stripNamespace(v,fields[k],dropped,k) end
        rawset(t,k,v)
    end
    M.installed[env]={client=client,fallbacks=options and options.fallbacks==true,dropped=dropped}
    return dropped
end
return M
